import { styled } from '@mui/material/styles'
import { useSortable } from '@dnd-kit/sortable'
import { useCallback } from 'react'
import type { MouseEventHandler, ReactNode } from 'react'

export interface CardDragInteractions {
    onClick: MouseEventHandler<HTMLElement>
    onContextMenu: MouseEventHandler<HTMLElement>
}

const CardDragSurface = styled('div')(({ theme }) => ({
    backgroundColor: theme.palette.background.paper,
    border: '1px solid',
    borderColor: theme.palette.divider,
    borderRadius: 10,
    boxShadow: 'var(--md2-card-shadow)',
    overflow: 'hidden',
    position: 'relative',
    '&[data-dragging="true"]': {
        boxShadow: 'var(--md2-card-drag-shadow)',
        opacity: 0,
    },
    '&[data-selected="true"]': { borderColor: theme.palette.primary.main },
    '&:hover': {
        borderColor: theme.palette.text.disabled,
        boxShadow: 'var(--md2-card-hover-shadow)',
    },
}))

const CardDragButton = styled('button')(({ theme }) => ({
    backgroundColor: 'transparent',
    border: 0,
    cursor: 'pointer',
    inset: 0,
    position: 'absolute',
    zIndex: 1,
    '&[data-dragging="true"]': { cursor: 'grabbing' },
    '&:focus-visible': {
        outline: `2px solid ${theme.palette.primary.main}`,
        outlineOffset: -2,
    },
}))

interface CardDragContainerProps {
    cardId: string
    cardPath: string
    children: ReactNode
    interactions: CardDragInteractions
    isBodyOpen: boolean
    isMobile: boolean
    isSelected: boolean
    onCardElementChange: (element: HTMLDivElement | null) => void
}

/** Lightweight sortable adapter that updates only card drag DOM around stable card content. */
export function CardDragContainer(props: CardDragContainerProps) {
    const {cardId, cardPath, children, interactions, isBodyOpen, isMobile, isSelected, onCardElementChange} = props
    const { onClick, onContextMenu } = interactions
    const sortable = useSortable({ id: cardPath })
    const { attributes, isDragging, listeners, setActivatorNodeRef, setNodeRef, transform, transition } = sortable
    const dragTranslation = transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : ''
    const transformStyle = `${dragTranslation}${isDragging ? ' rotate(2deg)' : ''}`.trim() || undefined
    const setCardElement = useCallback((element: HTMLDivElement | null) => {
        setNodeRef(element)
        onCardElementChange(element)
    }, [onCardElementChange, setNodeRef])

    return (
        <CardDragSurface
            data-card-path={cardPath}
            data-dragging={isDragging ? 'true' : undefined}
            data-selected={isSelected ? 'true' : undefined}
            onContextMenu={onContextMenu}
            ref={setCardElement}
            style={{ transform: transformStyle, transition }}
        >
            <CardDragButton
                {...attributes}
                {...listeners}
                aria-expanded={isBodyOpen}
                aria-haspopup="dialog"
                aria-label={`Drag ${cardId}`}
                onClick={onClick}
                ref={setActivatorNodeRef}
                data-dragging={isDragging ? 'true' : undefined}
                style={{ touchAction: isMobile ? 'pan-y' : 'none' }}
                type="button"
            />
            {children}
        </CardDragSurface>
    )
}

import { Box, Button, Tooltip } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import HelpCircleOutline from 'mdi-material-ui/HelpCircleOutline'
import Play from 'mdi-material-ui/Play'
import type { MouseEvent } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { CardHeader } from '../../../../data/data_types'
import { cardPopupService } from '../../../../services/card_popup_service'
import { agentStateDescription } from '../../../../services/agents/card_agent_state'
import { useCardAgentState } from '../../../hooks/use_agent_acknowledgements'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'

interface CardRunButtonProps {
    card: { header: Pick<CardHeader, 'internalId'> }
    context: ActionContext
}

/** Opens the card action selector and run popup, and surfaces the card's agent state. */
export function CardRunButton({ card, context }: CardRunButtonProps) {
    const agentState = useCardAgentState(card.header.internalId)
    const runningRun = useRunningActionForContext(context)
    const liveStatus = runningRun?.status
    const isQueued = liveStatus === 'queued'
    const isWaiting = liveStatus ? liveStatus === 'waitingForInput' : agentState === 'waiting for input'
    const isRunning = liveStatus ? liveStatus === 'running' : agentState === 'running'
    const isUnseen = !isQueued && !isWaiting && !isRunning && agentState === 'unseen result'
    const stateDescription = isQueued
        ? 'Action is queued'
        : isWaiting
            ? agentStateDescription('waiting for input')
            : isRunning && agentState !== 'running'
                ? 'Action is running'
                : agentStateDescription(agentState)
    const accent = isWaiting ? 'warning.main' : isUnseen ? 'info.main' : 'primary.main'
    const handleRun = (event: MouseEvent<HTMLButtonElement>) => {
        cardPopupService.toggleAction(context, event.currentTarget)
    }

    const button = (
        <Box
            sx={(theme) => ({
                borderRadius: 99,
                display: 'inline-flex',
                overflow: 'hidden',
                p: isRunning ? '1.5px' : 0,
                position: 'relative',
                ...(isRunning && {
                    '@keyframes md2-run-spin': { to: { transform: 'rotate(1turn)' } },
                    '&::before': {
                        animation: 'md2-run-spin 1s linear infinite',
                        background: `conic-gradient(from 0deg, ${theme.palette.primary.main}, transparent 55%)`,
                        content: '""',
                        inset: '-50%',
                        pointerEvents: 'none',
                        position: 'absolute',
                    },
                }),
            })}
        >
            <Button
                aria-label={stateDescription ? `Run â€” ${stateDescription}` : 'Run'}
                onClick={handleRun}
                size="small"
                startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                sx={{
                    bgcolor: 'background.paper',
                    borderColor: isRunning ? 'transparent' : isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    borderRadius: 99,
                    color: isWaiting ? 'warning.main' : isUnseen ? 'info.main' : undefined,
                    fontSize: 11.5,
                    height: 26,
                    minWidth: 0,
                    position: 'relative',
                    px: 1.25,
                    zIndex: 1,
                    '&:hover': { bgcolor: 'background.paper' },
                }}
                variant="outlined"
            >
                Run
            </Button>
            {isWaiting ? <HelpCircleOutline sx={{ color: accent, fontSize: 11, position: 'absolute', right: -2, top: -2, zIndex: 2 }} /> : null}
            {isUnseen ? <Circle sx={{ color: accent, fontSize: 8, position: 'absolute', right: 0, top: 0, zIndex: 2 }} /> : null}
        </Box>
    )

    return (
        <Tooltip title={stateDescription ?? ''}>{button}</Tooltip>
    )
}

