import { Box } from '@mui/material'
import { memo, useCallback, useEffect, useState } from 'react'
import { openFilesService, type OpenDocumentEventDetail } from '../../../services/open_files_service'
import { actionMarkdownDataSource } from '../../editor/action_markdown_data_source'
import { sameMarkdownTarget, type MarkdownDocumentTarget } from '../../editor/markdown_data_source'
import { MarkdownDocumentHistoryStore } from '../../editor/markdown_document_history_store'
import { MarkdownEditor } from '../../editor/markdown_editor'
import { ActionEditor, type ActionMarkdownPresentation } from './action_editor'
import { useOpenFiles } from '../../hooks/use_open_files'
import { actionService } from '../../../services/actions/action_service'
import { useRetainedActionDocument } from './use_retained_action_document'

interface ListActionEditorProps {
    cardTypes: string[]
    specialContextTypes: string[]
    states: string[]
}

/** Lifetime-stable list action editor surface and binding-owned undo store. */
export const ListActionEditor = memo(function ListActionEditor(props: ListActionEditorProps) {
    const { cardTypes, specialContextTypes, states } = props
    const { activeDocument } = useOpenFiles()
    const activeActionDocument = activeDocument?.kind === 'action' ? activeDocument : null
    const retainedActionDocument = useRetainedActionDocument()
    const retainedAction = retainedActionDocument?.getObject() ?? null
    const retainedPath = retainedAction?.sourcePath
    const actionExists = !!retainedPath && (
        !!actionService.getActionByPath(retainedPath)
        || actionService.draftStore.getDeletedDraftActions().some((candidate) => candidate.sourcePath === retainedPath)
    )
    const action = actionExists ? retainedAction : null
    const [historyStore] = useState(() => new MarkdownDocumentHistoryStore())
    const [presentation, setPresentation] = useState<ActionMarkdownPresentation | null>(null)

    const discardMarkdownTarget = useCallback((target: MarkdownDocumentTarget) => {
        historyStore.discardTarget(target)
        const activeTarget = actionMarkdownDataSource.getActiveTarget('list-action')
        if (sameMarkdownTarget(activeTarget, target)) actionMarkdownDataSource.setActiveActionTarget(null, true)
    }, [historyStore])

    useEffect(() => {
        const handleRemoved = (event: Event) => {
            const { document } = (event as CustomEvent<OpenDocumentEventDetail>).detail
            if (document.kind !== 'action') return

            historyStore.discardDocument(document)
            const activeTarget = actionMarkdownDataSource.getActiveTarget('list-action')
            if (activeTarget?.document === document) {
                actionMarkdownDataSource.setActiveActionTarget(null)
                setPresentation(null)
            }
        }
        openFilesService.addEventListener('removed', handleRemoved)

        return () => openFilesService.removeEventListener('removed', handleRemoved)
    }, [historyStore])

    useEffect(() => () => actionMarkdownDataSource.setActiveActionTarget(null), [])

    return (
        <Box
            data-testid="list-action-editor"
            hidden={!activeActionDocument}
            sx={{ display: activeActionDocument ? 'contents' : 'none' }}
        >
            {action && retainedActionDocument ? (
                <ActionEditor
                    actionDocument={retainedActionDocument}
                    cardTypes={cardTypes}
                    discardMarkdownTarget={discardMarkdownTarget}
                    onMarkdownPresentationChange={setPresentation}
                    specialContextTypes={specialContextTypes}
                    states={states}
                />
            ) : null}
            <Box hidden={!presentation} sx={{ flex: 1, minHeight: 0, order: 1, overflowY: 'auto' }}>
                <MarkdownEditor
                    binding="list-action"
                    dataSource={actionMarkdownDataSource}
                    flushOnBlur
                    historyStore={historyStore}
                    placeholders={presentation?.placeholders}
                    toolbarContents={presentation?.toolbarContents}
                />
            </Box>
        </Box>
    )
})

import { Alert, Box, Button, Stack, Typography } from '@mui/material'
import { useEffect, useState } from 'react'
import type { ActionDefinition } from '../../../data/action_types'
import {
    ACTION_DRAFT_CHANGED_EVENT,
    actionService,
    type ActionDraftChangedDetail,
} from '../../../services/actions/action_service'
import { dialogService } from '../../../services/dialog_service'
import { openFilesService } from '../../../services/open_files_service'
import { useWorktrees } from '../../hooks/use_worktrees'
import { ActionDefinitionFields } from './action_definition_fields'
import { ACTION_DEFINITION_TAB } from './action_phrase_editor_state'

interface ActionEditorContentProps {
    action: ActionDefinition
    cardTypes: string[]
    sourcePath: string
    specialContextTypes: string[]
    states: string[]
}

/** Definition and recovery region backed directly by ActionService. */
export function ActionEditorContent(props: ActionEditorContentProps) {
    const { action, cardTypes, sourcePath, specialContextTypes, states } = props
    const [, setRevision] = useState(0)
    useEffect(() => {
        const handleChanged = (event: Event) => {
            const { path } = (event as CustomEvent<ActionDraftChangedDetail>).detail
            if (path === sourcePath) setRevision((current) => current + 1)
        }
        actionService.addEventListener(ACTION_DRAFT_CHANGED_EVENT, handleChanged)

        return () => actionService.removeEventListener(ACTION_DRAFT_CHANGED_EVENT, handleChanged)
    }, [sourcePath])
    const draft = actionService.draftStore.getDraft(sourcePath)
    const { conflict, definition, deleted, error: saveError, saving, validation } = draft
    const activeTab = (actionService.getActionByPath(sourcePath) ?? action).editorState?.selectedTab ?? ACTION_DEFINITION_TAB
    const openDocument = openFilesService.findDocument(action)
    const canRetry = !!saveError && validation.valid && !!openDocument?.dirty && !conflict && !saving
    const status = saveError ? 'Save failed. Retry to save changes.' : validation.valid ? null : 'Fix validation errors to save.'
    const showActionContent = definition.type !== 'agent' || activeTab === ACTION_DEFINITION_TAB || !!saveError || deleted || !!conflict
    const worktrees = useWorktrees()

    useEffect(() => {
        if (validation.error) dialogService.error(validation.error, { title: 'Invalid action' })
    }, [validation.error])
    const handleRetry = () => actionService.draftStore.retryDraft(sourcePath)
    const handleRecreateDeleted = () => actionService.draftStore.recreateDeletedDraft(sourcePath)
    const handleDiscardDeleted = () => {
        actionService.draftStore.discardDeletedDraft(sourcePath)
        const document = openFilesService.getSnapshot().documents.find((candidate) => (
            candidate.kind === 'action' && candidate.getObject().id === action.id
        ))
        if (document) openFilesService.closeDocument(document)
    }
    const handleKeepMine = () => actionService.draftStore.keepDraft(sourcePath)
    const handleReloadExternal = () => actionService.draftStore.reloadDraft(sourcePath)

    return (
        <Box
            data-testid="action-editor-content"
            hidden={!showActionContent}
            sx={{ flex: activeTab === ACTION_DEFINITION_TAB || definition.type !== 'agent' ? 1 : '0 0 auto', minHeight: 0, order: 1, overflowY: 'auto', p: 2 }}
        >
            {saveError ? (
                <Alert action={<Button color="inherit" disabled={!canRetry} onClick={handleRetry} size="small">Retry save</Button>} severity="error" sx={{ mb: 2 }}>
                    {saveError}
                </Alert>
            ) : null}
            {deleted ? (
                <Alert
                    action={(
                        <Stack direction="row" spacing={1}>
                            <Button color="inherit" disabled={!validation.valid || saving} onClick={handleRecreateDeleted} size="small">Recreate file</Button>
                            <Button color="inherit" onClick={handleDiscardDeleted} size="small">Discard draft</Button>
                        </Stack>
                    )}
                    severity="warning"
                    sx={{ mb: 2 }}
                >
                    This action file was deleted outside the editor. Recreate it or discard this draft.
                </Alert>
            ) : null}
            {conflict ? (
                <Alert
                    action={(
                        <Stack direction="row" spacing={1}>
                            <Button color="inherit" onClick={handleKeepMine} size="small">Keep my changes</Button>
                            <Button color="inherit" onClick={handleReloadExternal} size="small">Reload from disk</Button>
                        </Stack>
                    )}
                    severity="warning"
                    sx={{ mb: 2 }}
                >
                    This action was changed outside the editor while you had unsaved edits.
                </Alert>
            ) : null}
            {(definition.type !== 'agent' || activeTab === ACTION_DEFINITION_TAB) ? (
                <ActionDefinitionFields
                    actions={actionService.getActions()}
                    cardTypes={cardTypes}
                    sourcePath={sourcePath}
                    specialContextTypes={specialContextTypes}
                    states={states}
                    worktrees={worktrees}
                />
            ) : null}
            {status && (definition.type !== 'agent' || activeTab === ACTION_DEFINITION_TAB) ? (
                <Typography color={validation.valid ? 'text.secondary' : 'error'} sx={{ mt: 1 }} variant="caption">{status}</Typography>
            ) : null}
        </Box>
    )
}

import {
    Divider, FormControlLabel, FormHelperText, MenuItem, Paper, Stack, Switch, Grid,
} from '@mui/material'
import type { ChangeEvent, MouseEvent } from 'react'
import { memo, useEffect, useState } from 'react'
import type { ActionDefinition, RawActionDefinition } from '../../../data/action_types'
import type { WorktreeRecord } from '../../../data/data_types'
import {
    ACTION_DRAFT_CHANGED_EVENT,
    actionService,
    type ActionDraftChangedDetail,
} from '../../../services/actions/action_service'
import { useProjectState } from '../../hooks/use_project_state'
import { ActionAgentCapabilityFields } from '../agent/action_agent_capability_fields'
import { ActionEditorField } from './action_editor_field'
import { ActionFilterEditor } from './action_filter_editor'
import { ActionLinkListEditor } from './action_link_list_editor'
import { ActionOnRulesEditor } from './action_on_rules_editor'
import { ActionSectionLabel } from '../shared/action_section_label'
import { ActionEditorTextField } from './action_editor_text_field'

const ICON_FILE_PATTERN = /\.(svg|png|jpe?g|gif|webp)$/iu
const EMPTY_REPOSITORY_FILES: string[] = []

interface ActionDefinitionFieldsProps {
    actions: ActionDefinition[]
    cardTypes: string[]
    sourcePath: string
    specialContextTypes: string[]
    states: string[]
    worktrees: WorktreeRecord[]
}

export const ActionDefinitionFields = memo(function ActionDefinitionFields(props: ActionDefinitionFieldsProps) {
    const {
        actions, cardTypes, sourcePath,
        specialContextTypes, states, worktrees,
    } = props
    const { snapshot } = useProjectState()
    const repositoryFiles = snapshot?.repositoryFiles ?? EMPTY_REPOSITORY_FILES
    const [, setDraftRevision] = useState(0)
    useEffect(() => {
        let previousDraft = actionService.draftStore.getDraft(sourcePath)
        const handleChanged = (event: Event) => {
            const { path } = (event as CustomEvent<ActionDraftChangedDetail>).detail
            if (path !== sourcePath) return

            const nextDraft = actionService.draftStore.getDraft(sourcePath)
            if (nextDraft === previousDraft) return

            previousDraft = nextDraft
            setDraftRevision((current) => current + 1)
        }
        actionService.addEventListener(ACTION_DRAFT_CHANGED_EVENT, handleChanged)

        return () => actionService.removeEventListener(ACTION_DRAFT_CHANGED_EVENT, handleChanged)
    }, [sourcePath])
    const { definition, validation } = actionService.draftStore.getDraft(sourcePath)
    const errors = validation.error && validation.field ? { [validation.field]: validation.error } : {}
    const errorIndex = validation.index
    const selectableActions = actions.filter(({ id }) => id !== definition.id)
    // `stageDraft` deliberately fires no events, so controls that render straight from the
    // draft (selects, switches, list editors) need a local revision bump to show the new value.
    const handleDefinitionChange = (nextDefinition: RawActionDefinition) => {
        actionService.draftStore.stageDraft(sourcePath, nextDefinition)
        setDraftRevision((current) => current + 1)
    }
    /** Staging without a re-render, for fields that keep their own keystroke state. */
    const stageDefinition = (nextDefinition: RawActionDefinition) => {
        actionService.draftStore.stageDraft(sourcePath, nextDefinition)
    }
    const handleDefinitionCommit = () => actionService.draftStore.commitDraft(sourcePath)
    const iconPaths = repositoryFiles.filter((path) => ICON_FILE_PATTERN.test(path))
    if (definition.icon && !iconPaths.includes(definition.icon)) iconPaths.unshift(definition.icon)
